package main

import (
	"fmt"
)

const MOD int64 = 1000000007

var dp [2020][2020]int64

func main() {
	var n, m, k int
	fmt.Scan(&n, &m, &k)

	maxNM := n
	if m > maxNM {
		maxNM = m
	}

	for i := 0; i < maxNM; i++ {
		for j := 0; j <= i; j++ {
			if j == 0 {
				dp[j][i] = 1
			} else {
				dp[j][i] = (dp[j][i-1] + dp[j-1][i-1]) % MOD
			}
		}
	}

	res := (dp[2*k][n-1] * dp[2*k][m-1]) % MOD
	fmt.Println(res)
}

